const data = $json;

const transcript = data["Conversation Transcript"] || "";

return {
  json: {
    salesperson_name: data["Salesperson Name"] || "",
    customer_name: data["Customer Name"] || "",
    company_name: data["Company"] || "",
    product_service: data["Product/Service"] || "",
    sales_stage: data["Sales Stage"] || "",
    sales_goal: data["Sales Goal"] || "",
    transcript: transcript.trim(),

    transcript_length: transcript.length,

    submitted_at: new Date().toISOString()
  }
};

function parseAIOutput(value) {
  if (!value) {
    return {};
  }

  // Already an object
  if (typeof value === "object") {
    return value;
  }

  let text = String(value).trim();

  // Remove markdown code fences
  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // First attempt
  try {
    return JSON.parse(text);
  } catch (e) {}

  // Sometimes the AI returns escaped JSON
  try {
    const unescaped = text
      .replace(/\\"/g, '"')
      .replace(/\\n/g, "\n");

    return JSON.parse(unescaped);
  } catch (e) {}

  // Try to extract the JSON object
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");

  if (start !== -1 && end !== -1) {
    try {
      return JSON.parse(text.substring(start, end + 1));
    } catch (e) {}
  }

  return {};
}


// ================================
// GET DATA FROM PREVIOUS AGENTS
// ================================

const normalized = $("Normalize Conversation").first().json;

const analyzerRaw =
  $("Conversation Analyzer Agent").first().json.output;

const discoveryRaw =
  $("Discovery Coach").first().json.output;

const objectionRaw =
  $("Objection & Closing Coach").first().json.output;

const dealRaw =
  $("Deal Risk & Action Planner").first().json.output;


// Parse AI outputs
const analyzer = parseAIOutput(analyzerRaw);
const discovery = parseAIOutput(discoveryRaw);
const objection = parseAIOutput(objectionRaw);
const deal = parseAIOutput(dealRaw);


// ================================
// FINAL REPORT
// ================================

return [
  {
    json: {

      report_type: "AI Sales Coach Report",

      // ----------------------------
      // LEAD INFORMATION
      // ----------------------------

      lead_information: {
        salesperson: normalized.salesperson_name || "Unknown",
        customer: normalized.customer_name || "Unknown",
        company: normalized.company_name || "Unknown",
        product_service: normalized.product_service || "Unknown",
        sales_stage: normalized.sales_stage || "Unknown"
      },


      // ----------------------------
      // DEAL OVERVIEW
      // ----------------------------

      deal_overview: {
        deal_health: deal.deal_health || "UNKNOWN",
        deal_score: deal.deal_score ?? 0,
        risk_level: deal.risk_level || "UNKNOWN",
        deal_summary: deal.deal_summary || ""
      },


      // ----------------------------
      // CUSTOMER INSIGHTS
      // ----------------------------

      customer_insights: {

        pain_points:
          analyzer.customer_pain_points ||
          analyzer.pain_points ||
          [],

        needs:
          analyzer.customer_needs ||
          analyzer.needs ||
          [],

        goals:
          analyzer.customer_goals ||
          analyzer.goals ||
          [],

        objections:
          objection.objections ||
          [],

        buying_signals:
          deal.buying_signals ||
          analyzer.buying_signals ||
          []
      },


      // ----------------------------
      // SALES PERSON PERFORMANCE
      // ----------------------------

      salesperson_performance: {

        overall_score:
          discovery.overall_score ??
          null,

        category_scores:
          discovery.category_scores ||
          {},

        strengths:
          discovery.strengths ||
          [],

        weaknesses:
          discovery.weaknesses ||
          [],

        missed_opportunities:
          discovery.missed_opportunities ||
          [],

        objection_handling_score:
          objection.handling_quality_score ??
          null
      },


      // ----------------------------
      // DEAL ASSESSMENT
      // ----------------------------

      deal_assessment: {

        decision_maker_status:
          deal.decision_maker_status ||
          "UNKNOWN",

        budget_status:
          deal.budget_status ||
          "UNKNOWN",

        timeline_status:
          deal.timeline_status ||
          "UNKNOWN",

        next_step_status:
          deal.next_step_status ||
          "UNKNOWN"
      },


      // ----------------------------
      // DEAL RISKS
      // ----------------------------

      deal_risks:
        deal.deal_risks ||
        [],


      // ----------------------------
      // MISSING INFORMATION
      // ----------------------------

      missing_information:
        deal.missing_information ||
        [],


      // ----------------------------
      // RECOMMENDED ACTION
      // ----------------------------

      recommended_action: {

        next_step:
          deal.recommended_next_step ||
          "",

        follow_up_timing:
          deal.recommended_follow_up_timing ||
          "",

        recommended_contact:
          deal.recommended_contact ||
          "",

        message:
          deal.recommended_message ||
          ""
      },


      // ----------------------------
      // ACTION PLAN
      // ----------------------------

      action_plan:
        deal.action_plan ||
        [],


      // ----------------------------
      // FINAL COACHING PRIORITY
      // ----------------------------

      salesperson_priority:
        deal.salesperson_priority ||
        "",


      // ----------------------------
      // CONFIDENCE
      // ----------------------------

      confidence:
        deal.deal_confidence ??
        null,


      // ----------------------------
      // TIMESTAMP
      // ----------------------------

      processed_at:
        new Date().toISOString()
    }
  }
];
